  [UnityTest,Category("WhistleDiscovery")]public IEnumerator HighlightFlagsCategoriesOcclusionAndCollection(){var go=f.Child("Useful story object");var h=go.AddComponent<WhistleHighlightable>();h.highlightId="fixture.story";h.transform.position=f.camera.transform.position+Vector3.forward*2;var c=new WhistleContext(s,f.camera.transform.position,Vector3.forward,WhistleKind.Tap,0,1,"SchoolCEEP","room");h.category=WhistleCategory.Useful;Assert.That(h.Reveal(c,true),Is.True);h.category=WhistleCategory.Path;Assert.That(h.Reveal(c,true),Is.True);h.category=WhistleCategory.Story;Assert.That(h.Reveal(c,true),Is.True);Assert.That(h.ThroughWall,Is.True);h.Clear();h.range=1;Assert.That(h.Reveal(c,false),Is.False);h.range=10;h.requiredFlag="missing";Assert.That(h.Reveal(c,false),Is.False);h.requiredFlag=WhistleSystem.LoreFlag;Assert.That(h.Reveal(c,false),Is.True);h.hiddenWhenItemOwned="fixture.item";f.inventory.Add(new InventoryItem{id="fixture.item"});h.Tick(.1f);Assert.That(h.Visible,Is.False);yield return null;}
