  [UnityTest,Category("WhistleDiscovery")]public IEnumerator RestoringBeforeDiscoveryCancelsItsPendingWhispers(){var go=f.Child("Discovery callbacks");go.SetActive(false);var discovery=go.AddComponent<WhistleSchoolDiscovery>();discovery.owner=s;go.SetActive(true);Assert.That(s.BlowTap(),Is.True);s.LearnLore();s.State.discovered=false;s.State.cooldownRemaining=0;s.BlowTap();Assert.That(BeforeDemolitionChapterFixture.Private<int>(discovery,"step"),Is.EqualTo(0));s.Restore(new WhistleState{owned=true});yield return null;Assert.That(BeforeDemolitionChapterFixture.Private<int>(discovery,"step"),Is.EqualTo(-1));Assert.That(BeforeDemolitionChapterFixture.Private<bool>(s,"loreCommentPending"),Is.False);}
  static Texture2D CaptureSense(Camera camera,RenderTexture target){RenderPipeline.SubmitRenderRequest(camera,new RenderPipeline.StandardRequest{destination=target,isPreview=false});RenderTexture.active=target;var image=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,target.width,target.height),0,0);image.Apply();return image;}
  static float Difference(Texture2D a,Texture2D b){var x=a.GetPixels32();var y=b.GetPixels32();long total=0;for(int i=0;i<x.Length;i++)total+=Math.Abs(x[i].r-y[i].r)+Math.Abs(x[i].g-y[i].g)+Math.Abs(x[i].b-y[i].b);return total/(x.Length*765f);}
